420	    /// Whether a spec of this kind is an option its long name selects, as `--name`: a
421	    /// [`Bool`](Self::Bool), a [`Switch`](Self::Switch) or a [`Value`](Self::Value).
422	    ///
423	    /// The parser selects a spec of any other kind otherwise, or never by its long name: a
424	    /// bare `--` selects the [`Literal`](Self::Literal), an [`Arg`](Self::Arg) or
425	    /// [`Args`](Self::Args) takes bare arguments, an [`Accumulator`](Self::Accumulator) is
426	    /// selected by its short alias alone, as `-v`, and [`None`](Self::None) ends a spec list.
427	    /// The C parser of long arguments has a branch for an accumulator that this predicate
428	    /// leaves unreachable, as the C macro does; no spec of the CLI is an accumulator.
429	    ///
430	    /// The C macro takes a spec and reads its `type`; here the predicate is the kind's, which
431	    /// a ported spec's kind answers. It computes on its argument alone, so it is a `const fn`.
432	    /// A C spec whose `type` holds a value `opt.h` does not name, which the macro reports as
433	    /// no option, has no `Kind`: its conversion refuses it before the predicate is reached.
434	    ///
435	    /// ```
436	    /// use libgit2_crustify::git2::src::cli::opt::Kind;
437	    ///
438	    /// assert!(Kind::Bool.is_option());
439	    /// assert!(Kind::Value.is_option());
440	    /// assert!(!Kind::Accumulator.is_option());
441	    /// assert!(!Kind::Args.is_option());
442	    /// ```
443	    ///
444	    /// Replaces `mac::spec_is_option_type`
445	    #[doc(alias = "spec_is_option_type")]
446	    #[must_use]
447	    #[inline]
448	    pub const fn is_option(self) -> bool {
449	        matches!(self, Self::Bool | Self::Switch | Self::Value)
450	    }
451	}
452	
453	/// Whether a parser built with `flags` parses GNU-style, as `getopt_long` does, letting
454	/// options follow bare arguments (`file1 --help file2`), which it reorders in place: always
455	/// under [`ParseFlags::FORCE_GNU`]; under [`ParseFlags::GNU`] alone, unless the environment
456	/// sets `POSIXLY_CORRECT`, to any value, the empty one included; never without either. The
457	/// flags that ask nothing of the parsing style, those no constant names included, do not
458	/// change it.
459	///
460	/// The C reads the variable with `getenv`, whose result it compares with NULL, which is
461	/// [`std::env::var_os`] returning `Some`: libc's `getenv` takes its `std` route. The variable
462	/// is read on every call, so a change to the environment between two parsers changes the
463	/// second one's style. On Windows the C reads it with `_wgetenv` where `UNICODE` is defined,
464	/// which `var_os` does too, and the crate is built for Linux alone.
465	///
466	/// ```
467	/// use libgit2_crustify::git2::src::cli::opt::{ParseFlags, uses_gnu_style};
468	///
469	/// assert!(uses_gnu_style(ParseFlags::FORCE_GNU));
470	/// assert!(!uses_gnu_style(ParseFlags::DEFAULT));
471	/// ```
472	///
473	/// Replaces `fn::support_gnu_style`
474	#[doc(alias = "support_gnu_style")]
475	#[must_use]
476	pub fn uses_gnu_style(flags: ParseFlags) -> bool {
477	    if flags.contains(ParseFlags::FORCE_GNU) {
478	        return true;
479	    }
480	    flags.contains(ParseFlags::GNU) && std::env::var_os(POSIXLY_CORRECT).is_none()
481	}
482	
483	/// What a parse does when it meets a spec: the spec's [`Kind`] together with the variable it
484	/// writes, which C keeps in a spec's `type` and its type-erased `value`.
485	///
486	/// Each kind writes one type of variable, which its variant holds; `None` in a variant is a
487	/// spec with no variable, which C parses without writing anything. The variables are
488	/// [`Cell`]s, since one variable may serve several specs, as a mode two switches select does:
489	///
490	/// - a [`Kind::Bool`] spec sets its `c_int` to `1` when given and to `0` when given negated, as
491	///   `--no-<name>`;
492	/// - a [`Kind::Switch`] spec sets it to the spec's switch value;
493	/// - a [`Kind::Accumulator`] spec adds the spec's switch value to it, or `1` for a switch value of
494	///   `0`;
495	/// - a [`Kind::Value`] or [`Kind::Arg`] spec stores the argument it took, as an [`Arg`]; and
496	/// - a [`Kind::Args`] spec stores where the arguments it took start, as an [`ArgsSlot`].
497	///
498	/// [`Kind::None`], the kind of the zeroed spec that ends a table, and [`Kind::Literal`], the
499	/// bare `--`, write nothing.
500	#[derive(Clone, Copy, Debug)]
501	pub enum Target<'p> {
502	    /// The end of a spec table.
503	    None,
504	    /// A flag set to `1`, or to `0` by its `no-` form.
505	    Bool(Option<&'p Cell<c_int>>),
506	    /// A variable set to the spec's switch value.
507	    Switch(Option<&'p Cell<c_int>>),
508	    /// A counter the spec's switch value is added to each time the option is given.
509	    Accumulator(Option<&'p Cell<c_int>>),
510	    /// The value the option was given.
511	    Value(Option<&'p Cell<Option<Arg<'p>>>>),
512	    /// The bare `--` after which every argument is literal.
513	    Literal,
514	    /// The bare argument this spec matched.
515	    Arg(Option<&'p Cell<Option<Arg<'p>>>>),
516	    /// The remaining arguments, from the first one this spec matched.
517	    Args(Option<&'p ArgsSlot<'p>>),
518	}
519	
520	impl Target<'_> {
521	    /// The kind of spec that writes this target.
522	    #[must_use]
523	    pub const fn kind(&self) -> Kind {
524	        match self {
525	            Self::None => Kind::None,
526	            Self::Bool(_) => Kind::Bool,
527	            Self::Switch(_) => Kind::Switch,
528	            Self::Accumulator(_) => Kind::Accumulator,
529	            Self::Value(_) => Kind::Value,
530	            Self::Literal => Kind::Literal,
531	            Self::Arg(_) => Kind::Arg,
532	            Self::Args(_) => Kind::Args,
533	        }
534	    }
535	}
536	
537	/// A spec's fields set one by one, each taking and returning the spec, so that a spec reads as
538	/// C's initialiser does, and a table as C's array of them, ended by the zeroed
539	/// [`Spec::default`]:
540	///
541	/// ```
542	/// use core::cell::Cell;
543	///
544	/// use libgit2_crustify::git2::src::cli::opt::{Spec, SpecTable, Target, Usage};
545	///
546	/// let debug = Cell::new(0);
547	/// let specs = [
548	///     Spec::new(Target::Bool(Some(&debug)))
549	///         .with_name(c"debug")
