632	impl<'p> ArgsSlot<'p> {
633	    /// A slot no parse has written: it holds C's `NULL`.
634	    #[must_use]
635	    pub const fn new() -> Self {
636	        Self(Cell::new(ptr::null_mut()))
637	    }
638	
639	    /// Whether a parse, or [`set`](Self::set), has stored a position.
640	    #[must_use]
641	    pub fn is_set(&self) -> bool {
642	        !self.0.get().is_null()
643	    }
644	
645	    /// Stores the start of `tail`, the arguments from the first one a spec took, as C stores
646	    /// `&args[idx]`.
647	    pub fn set(&self, tail: &[Arg<'p>]) {
648	        self.0.set(tail.as_ptr().cast_mut());
649	    }
650	
651	    /// Empties the slot, as [`new`](Self::new) builds it.
652	    pub fn clear(&self) {
653	        self.0.set(ptr::null_mut());
654	    }
