656	    /// The arguments of `args` from the stored position on, or `None` when the slot is empty or
657	    /// its position is not within `args`: its first element through one past its last.
658	    ///
659	    /// The position is compared by address alone, so a slot written for another array finds
660	    /// nothing in this one.
661	    #[must_use]
662	    pub fn get_in<'x>(&self, args: &'x [Arg<'p>]) -> Option<&'x [Arg<'p>]> {
663	        let start = self.0.get();
664	        if start.is_null() {
665	            return None;
666	        }
667	        let base = args.as_ptr().addr();
668	        let offset = start.addr().checked_sub(base)?;
669	        let index = offset / size_of::<Arg<'p>>();
670	        if offset % size_of::<Arg<'p>>() != 0 {
671	            return None;
672	        }
673	        args.get(index..)
674	    }
675	}
