702	    /// let specs = [Spec::default()];
703	    /// let table = SpecTable::new(&specs).unwrap();
704	    /// let mut args = [Arg::new(c"file")];
705	    /// let parser = Parser::new(table, &mut args, ParseFlags::FORCE_GNU);
706	    /// assert_eq!((parser.as_ref().args_len(), parser.as_ref().idx()), (1, 0));
707	    /// assert!(parser.as_ref().needs_sort());
708	    /// ```
709	    ///
710	    /// Replaces `fn::cli_opt_parser_init`
711	    #[doc(alias = "cli_opt_parser_init")]
712	    #[must_use]
713	    pub fn new(specs: SpecTable<'p>, args: &'p mut [Arg<'p>], flags: ParseFlags) -> Self {
714	        let mut parser = Self::zeroed();
715	        {
716	            let mut state = parser.as_mut();
717	            state.set_specs(Some(specs));
718	            state.set_args(args);
719	            state.set_flags(flags);
720	            state.set_needs_sort(uses_gnu_style(flags));
721	        }
722	        parser
723	    }
