726	/// How a long argument, `--<arg>`, selects the spec [`find_long`] finds for it.
727	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
728	enum LongForm<'p> {
729	    /// By the spec's name alone, as `--name`, or the bare `--` of a [`Kind::Literal`] spec.
730	    Plain,
731	    /// By the `no-` form of a [`Kind::Bool`] spec's name, as `--no-name`, which sets it to 0.
732	    Negated,
733	    /// By a [`Kind::Value`] spec's name with its value after an `=`, as `--name=value`: the
734	    /// value, or `None` for the empty one of `--name=`.
735	    Valued(Option<&'p CStr>),
736	}
737	
738	/// The spec a long argument selects, with how it selects it: `arg` is the argument after its
739	/// `--`, as `debug` of `--debug`, the empty string for the bare `--`. `None` when the parser
740	/// has no table, or no spec of its table matches.
741	///
742	/// The table's specs are tried in order, and the first that matches is the one: within each,
743	/// a [`Kind::Literal`] spec matches the bare `--`, a [`Kind::Bool`] spec its name after `no-`,
744	/// a spec whose kind [`is_option`](Kind::is_option) its name, and a [`Kind::Value`] spec its
745	/// name before the first `=` of `arg`. Names compare as bytes, as `strcmp` compares them.
746	///
747	/// The C compares `arg` after its `no-` with a bool spec's name without checking that the spec
748	/// has one, which reads through a null pointer: a bool spec without a name matches no `no-`
749	/// argument here, as it matches no other.
750	///
751	/// Replaces `fn::spec_for_long`
752	#[doc(alias = "spec_for_long")]
753	fn find_long<'p>(
754	    parser: ParserRef<'_, 'p>,
755	    arg: &'p CStr,
756	) -> Option<(SpecRef<'p, 'p>, LongForm<'p>)> {
757	    let bytes = arg.to_bytes();
758	    let eql = bytes.iter().position(|&b| b == b'=');
759	    parser.specs()?.iter().find_map(|spec| {
760	        let kind = spec.kind();
761	        let name = spec.name().map(CStr::to_bytes);
762	        if kind == Some(Kind::Literal) && bytes.is_empty() {
763	            return Some((spec, LongForm::Plain));
764	        }
765	        if kind == Some(Kind::Bool) && name.is_some() && bytes.strip_prefix(b"no-") == name {
766	            return Some((spec, LongForm::Negated));
767	        }
768	        if kind.is_some_and(Kind::is_option) && name == Some(bytes) {
769	            return Some((spec, LongForm::Plain));
770	        }
771	        if kind == Some(Kind::Value)
772	            && let (Some(name), Some(at)) = (name, eql)
773	            && bytes.get(..at) == Some(name)
774	        {
775	            let value = arg
776	                .to_bytes_with_nul()
777	                .get(at + 1..)
778	                .and_then(|rest| CStr::from_bytes_until_nul(rest).ok())
779	                .filter(|value| !value.is_empty());
780	            return Some((spec, LongForm::Valued(value)));
781	        }
782	        None
783	    })
784	}
