786	/// The spec a short option selects, with the value it carries: `arg` is the rest of the
787	/// argument from the option's character on, as `ofile` of `-ofile`, or `vd` of the bundle `-xvd`
788	/// once `x` is parsed. `None` when the parser has no table, or no spec of its table has that
789	/// character as its alias.
790	///
791	/// The first spec whose alias is the character is the one. A [`Kind::Value`] spec takes the rest
792	/// of `arg` after it as its value, as `file` of `-ofile`, when there is any; every other spec,
793	/// and a value spec at the end of `arg`, carries none.
794	///
795	/// The C compares the character with every spec's alias, `0` for a spec without one, so that
796	/// an empty `arg`, the bare `-`, selects the first spec without an alias, and a value spec
797	/// without one then has the byte after the string's end read: a spec without an alias matches
798	/// no short option here, and the empty `arg` matches none.
799	///
800	/// Replaces `fn::spec_for_short`
801	#[doc(alias = "spec_for_short")]
802	fn find_short<'p>(
803	    parser: ParserRef<'_, 'p>,
804	    arg: &'p CStr,
805	) -> Option<(SpecRef<'p, 'p>, Option<&'p CStr>)> {
806	    let first = *arg.to_bytes().first()?;
807	    let spec = parser
808	        .specs()?
809	        .iter()
810	        .find(|spec| spec.alias().map(NonZero::get) == Some(first))?;
811	    let value = if spec.kind() == Some(Kind::Value) {
812	        arg.to_bytes_with_nul()
813	            .get(1..)
814	            .and_then(|rest| CStr::from_bytes_until_nul(rest).ok())
815	            .filter(|value| !value.is_empty())
816	    } else {
817	        None
818	    };
819	    Some((spec, value))
820	}
