822	/// The spec the parser's next bare argument selects: the [`Kind::Arg`] spec of the table that
823	/// as many bare arguments as the parser's [`arg_idx`](ParserRef::arg_idx) precede, which it
824	/// then counts as matched, or, when a [`Kind::Args`] spec comes first, that spec, which takes
825	/// every argument left and counts nothing. `None` when the parser has no table, or every
826	/// argument spec is matched.
827	///
828	/// Replaces `fn::spec_for_arg`
829	#[doc(alias = "spec_for_arg")]
830	fn find_arg<'p>(parser: &mut ParserMut<'_, 'p>) -> Option<SpecRef<'p, 'p>> {
831	    let specs = parser.as_ref().specs()?;
832	    let arg_idx = parser.as_ref().arg_idx();
833	    let mut args = 0;
834	    for spec in specs.iter() {
835	        match spec.kind() {
836	            Some(Kind::Arg) if args == arg_idx => {
837	                parser.set_arg_idx(arg_idx.wrapping_add(1));
838	                return Some(spec);
839	            }
840	            Some(Kind::Arg) => args += 1,
841	            Some(Kind::Args) if args == arg_idx => return Some(spec),
842	            _ => {}
843	        }
844	    }
845	    None
846	}
