848	/// Whether the spec at `index` of `specs` starts or continues a choice: whether the spec after
849	/// it is one of the choices it offers, a spec of [`Usage::CHOICE`]. The last spec of the table,
850	/// and an index past it, are no choice.
851	///
852	/// Replaces `fn::spec_is_choice`
853	#[doc(alias = "spec_is_choice")]
854	fn is_choice(specs: SpecTable<'_>, index: usize) -> bool {
855	    index
856	        .checked_add(1)
857	        .and_then(|next| specs.get(next))
858	        .is_some_and(|next| next.usage().contains(Usage::CHOICE))
859	}
