861	/// Whether the spec at `index` of `specs` is a later choice of a choice before it.
862	fn is_later_choice(specs: SpecTable<'_>, index: usize) -> bool {
863	    specs
864	        .get(index)
865	        .is_some_and(|spec| spec.usage().contains(Usage::CHOICE))
866	}
