868	/// Counts as matched the [`Kind::Arg`] specs of the choice `spec` belongs to, once one of its
869	/// options is given, since a choice of switches and bare arguments takes one of them: the
870	/// parser's [`arg_idx`](ParserRef::arg_idx) moves past each argument spec of the choice. Nothing
871	/// changes when `spec` is not in the parser's table, or belongs to no choice.
872	///
873	/// The choice starts at the spec before `spec`'s run of [`Usage::CHOICE`] specs. The C steps
874	/// back over that run without a bound, before the table's start when its first spec is marked
875	/// [`Usage::CHOICE`]: the table's start ends the run here, as the start of its choice.
876	///
877	/// Replaces `fn::consume_choices`
878	#[doc(alias = "consume_choices")]
879	fn skip_choice_args<'p>(spec: SpecRef<'_, 'p>, parser: &mut ParserMut<'_, 'p>) {
880	    let Some(specs) = parser.as_ref().specs() else {
881	        return;
882	    };
883	    let Some(mut start) = specs.position(spec) else {
884	        return;
885	    };
886	    while start > 0 && is_later_choice(specs, start) {
887	        start -= 1;
888	    }
889	    if !is_choice(specs, start) {
890	        return;
891	    }
892	    let mut consumed = 0_usize;
893	    let mut index = start;
894	    loop {
895	        if specs.get(index).and_then(|s| s.kind()) == Some(Kind::Arg) {
896	            consumed += 1;
897	        }
898	        index += 1;
899	        if !is_later_choice(specs, index) {
900	            break;
901	        }
902	    }
903	    let arg_idx = parser.as_ref().arg_idx();
904	    parser.set_arg_idx(arg_idx.wrapping_add(consumed));
905	}
