907	/// Whether `spec` is one of `given`, the specs the arguments matched, compared by address, as C
908	/// compares spec pointers.
909	///
910	/// Replaces `fn::spec_included`
911	#[doc(alias = "spec_included")]
912	fn is_given(given: &[SpecRef<'_, '_>], spec: SpecRef<'_, '_>) -> bool {
913	    given.iter().any(|g| ptr::eq(g.as_ptr(), spec.as_ptr()))
914	}
