916	/// Checks that the arguments gave every required spec of `specs`, `given` being the specs they
917	/// matched: a spec of [`Usage::REQUIRED`], or, when it starts a choice, one of its choices. The
918	/// first requirement not given is the error: its spec, the first of its choice.
919	///
920	/// Replaces `fn::validate_required`
921	#[doc(alias = "validate_required")]
922	fn check_required<'p>(
923	    specs: SpecTable<'p>,
924	    given: &[SpecRef<'_, 'p>],
925	) -> Result<(), SpecRef<'p, 'p>> {
926	    let mut required = None;
927	    let mut met = false;
928	    for (index, spec) in specs.iter().enumerate() {
929	        let head = match required {
930	            Some(head) => head,
931	            None if spec.usage().contains(Usage::REQUIRED) => {
932	                met = false;
933	                spec
934	            }
935	            None => continue,
936	        };
937	        required = Some(head);
938	        met = met || is_given(given, spec);
939	        if !is_choice(specs, index) {
940	            if !met {
941	                return Err(head);
942	            }
943	            required = None;
944	            met = false;
945	        }
946	    }
947	    Ok(())
948	}
