966	/// Adds the step an [`Kind::Accumulator`] spec counts by, its switch value or `1` for `0`, to
967	/// `count`. C's `+=` on an `int` that overflows is undefined; here it wraps.
968	fn accumulate(count: &Cell<c_int>, spec: SpecRef<'_, '_>) {
969	    let step = match spec.switch_value() {
970	        0 => 1,
971	        step => step,
972	    };
973	    count.set(count.get().wrapping_add(step));
974	}
