976	/// The argument after the one being parsed, which a [`Kind::Value`] spec given no value of its
977	/// own takes, as `bar` of `--foo bar` or `-f bar`, whatever it looks like: the parser moves past
978	/// it. `None`, the parser unmoved, when no argument is left.
979	fn take_following<'p>(parser: &mut ParserMut<'_, 'p>) -> Option<&'p CStr> {
980	    let idx = parser.as_ref().idx();
981	    let value = parser.as_ref().args().get(idx).copied()?;
982	    parser.set_idx(idx + 1);
983	    Some(value.as_c_str())
984	}
