986	/// Parses the long argument at the parser's position, `--<name>`, which it moves past: the outcome
987	/// of the spec [`find_long`] finds for `<name>`, or [`Status::UnknownOption`] when it finds none.
988	///
989	/// The spec found writes its variable, if it has one: a [`Kind::Bool`] spec `1`, or `0` for its
990	/// `no-` form; a [`Kind::Switch`] spec its switch value; a [`Kind::Value`] spec the value after
991	/// its `=`, or else the next argument, which the parser then moves past too. A [`Kind::Literal`]
992	/// spec, the bare `--`, makes every later argument literal. A value spec given no value is
993	/// [`Status::MissingValue`], unless its value is optional, and an outcome of a choice counts
994	/// its argument specs as matched, as [`skip_choice_args`] does.
995	///
996	/// Replaces `fn::parse_long`
997	#[doc(alias = "parse_long")]
998	fn take_long<'p>(parser: &mut ParserMut<'_, 'p>) -> Opt<'p> {
999	    let mut opt = Opt::zeroed();
1000	    let idx = parser.as_ref().idx();
1001	    let Some(arg) = parser.as_ref().args().get(idx).copied() else {
1002	        return opt;
1003	    };
1004	    let arg = arg.as_c_str();
1005	    parser.set_idx(idx + 1);
1006	    let mut out = opt.as_mut();
1007	    out.set_arg(Some(arg));
1008	    let found = suffix(arg, 2).and_then(|name| find_long(parser.as_ref(), name));
1009	    let Some((spec, form)) = found else {
1010	        out.set_status(Status::UnknownOption);
1011	        return opt;
1012	    };
1013	    out.set_spec(Some(spec));
1014	    let mut value = None;
1015	    match spec.target() {
1016	        Some(Target::Literal) => parser.set_in_literal(true),
1017	        Some(Target::Bool(Some(flag))) => flag.set(c_int::from(form != LongForm::Negated)),
1018	        Some(Target::Accumulator(Some(count))) => accumulate(count, spec),
1019	        Some(Target::Switch(Some(mode))) => mode.set(spec.switch_value()),
1020	        Some(Target::Value(variable)) => {
1021	            value = match form {
1022	                LongForm::Valued(given) => given,
1023	                LongForm::Plain | LongForm::Negated => take_following(parser),
1024	            };
1025	            if let Some(variable) = variable {
1026	                variable.set(value.map(Arg::new));
1027	            }
1028	        }
1029	        _ => {}
1030	    }
1031	    out.set_value(value);
1032	    out.set_status(if lacks_value(spec, value) {
1033	        Status::MissingValue
1034	    } else {
1035	        Status::Ok
1036	    });
1037	    skip_choice_args(spec, parser);
1038	    opt
1039	}
