1041	/// Parses the short option at the parser's position: `-<c>`, or the next option of a bundle of
1042	/// them, as the `b` of `-abc` once `a` is parsed. The outcome of the spec [`find_short`] finds for
1043	/// the option's character, or [`Status::UnknownOption`] when it finds none.
1044	///
1045	/// The spec found writes its variable, if it has one, as [`take_long`]'s do, a [`Kind::Bool`]
1046	/// spec always `1`: a [`Kind::Value`] spec takes the rest of the argument as its value, as `foo` of
1047	/// `-ofoo`, or else the next argument. An option of any other kind followed by more of the bundle
1048	/// leaves the parser on the argument, at the bundle's next option; otherwise the parser moves past
1049	/// it, and past a value it took. The outcome's argument is the whole bundle, as C gives it.
1050	///
1051	/// An unknown option ends its bundle: the parser moves to the next argument, at its start. The C
1052	/// moves to the next argument but stays as far into it as it was into the bundle, so that it
1053	/// parses that argument from the wrong character, past its end when the argument is shorter.
1054	///
1055	/// Replaces `fn::parse_short`
1056	#[doc(alias = "parse_short")]
1057	fn take_short<'p>(parser: &mut ParserMut<'_, 'p>) -> Opt<'p> {
1058	    let mut opt = Opt::zeroed();
1059	    let (idx, in_short) = (parser.as_ref().idx(), parser.as_ref().in_short());
1060	    let Some(arg) = parser.as_ref().args().get(idx).copied() else {
1061	        return opt;
1062	    };
1063	    let arg = arg.as_c_str();
1064	    parser.set_idx(idx + 1);
1065	    let mut out = opt.as_mut();
1066	    out.set_arg(Some(arg));
1067	    let rest = in_short.checked_add(1).and_then(|at| suffix(arg, at));
1068	    let found = rest.and_then(|rest| Some((rest, find_short(parser.as_ref(), rest)?)));
1069	    let Some((rest, (spec, attached))) = found else {
1070	        parser.set_in_short(0);
1071	        out.set_status(Status::UnknownOption);
1072	        return opt;
1073	    };
1074	    out.set_spec(Some(spec));
1075	    let mut value = None;
1076	    match spec.target() {
1077	        Some(Target::Bool(Some(flag))) => flag.set(1),
1078	        Some(Target::Accumulator(Some(count))) => accumulate(count, spec),
1079	        Some(Target::Switch(Some(mode))) => mode.set(spec.switch_value()),
1080	        Some(Target::Value(variable)) => {
1081	            value = attached.or_else(|| take_following(parser));
1082	            if let Some(variable) = variable {
1083	                variable.set(value.map(Arg::new));
1084	            }
1085	        }
1086	        _ => {}
1087	    }
1088	    if spec.kind() != Some(Kind::Value) && rest.to_bytes().len() > 1 {
1089	        parser.set_in_short(in_short + 1);
1090	        parser.set_idx(idx);
1091	    } else {
1092	        parser.set_in_short(0);
1093	    }
1094	    out.set_value(value);
1095	    out.set_status(if lacks_value(spec, value) {
1096	        Status::MissingValue
