1147	/// The spec `arg` selects when the parser reorders its arguments GNU style, with whether a
1148	/// [`Kind::Value`] spec selected still needs a value from the next argument: `None` for an
1149	/// argument that is no option, or no option the parser knows.
1150	///
1151	/// A long argument, `--<name>`, selects what [`find_long`] finds, which needs a value unless
1152	/// it gave one after an `=`. A short one, `-<c>…`, is read as a bundle, to its last option or to
1153	/// the first that takes the rest as its value, as `-xvffile`'s `f`: that option is the one,
1154	/// which needs a value only when the bundle gave none. A bundle holding an unknown option, or
1155	/// the bare `-`, selects nothing, where the C selects the first spec without an alias for the
1156	/// bare `-` and reads past its end, as [`find_short`] describes.
1157	///
1158	/// Replaces `fn::spec_for_sort`
1159	#[doc(alias = "spec_for_sort")]
1160	fn find_for_sort<'p>(parser: ParserRef<'_, 'p>, arg: &'p CStr) -> Option<(SpecRef<'p, 'p>, bool)> {
1161	    let bytes = arg.to_bytes();
1162	    if bytes.starts_with(b"--") {
1163	        let (spec, form) = find_long(parser, suffix(arg, 2)?)?;
1164	        return Some((spec, !matches!(form, LongForm::Valued(_))));
1165	    }
1166	    if !bytes.starts_with(b"-") {
1167	        return None;
1168	    }
1169	    let mut at = 1;
1170	    loop {
1171	        let (spec, value) = find_short(parser, suffix(arg, at)?)?;
1172	        at += 1;
1173	        if value.is_some() || at >= bytes.len() {
1174	            return Some((spec, value.is_none()));
1175	        }
1176	    }
1177	}
