1179	/// Moves the options after the parser's position ahead of the bare arguments there, keeping
1180	/// their order and those of the bare arguments, each option with the value it takes from the
1181	/// next argument, so that `file1 --help file2` parses as `--help file1 file2`, as GNU
1182	/// `getopt_long` does: whether it moved any. The parser does it once: it no longer needs to.
1183	///
1184	/// An option is what [`find_for_sort`] selects. A bare `--` the parser knows, a
1185	/// [`Kind::Literal`] spec, ends the reordering: what follows it is literal. A [`Kind::Value`]
1186	/// spec that needs a value with no argument after it stops the reordering with the parser moved
1187	/// to it, so that the parse reports its missing value next, unless its value is optional
1188	/// ([`Usage::VALUE_OPTIONAL`]): the option is the last argument, and stays where it is. An
1189	/// option at the parser's first argument, which no parse gives this routine, moves nothing.
1190	///
1191	/// Two departures from the C, which reorders whatever its parser's state: a parser that has
1192	/// parsed a literal `--` reorders nothing, since every argument after it is literal, where the
1193	/// C moves the arguments that look like its options ahead of the others; and an option whose
1194	/// value is optional ends no reordering, where the C moves the parser to it past the bare
1195	/// arguments before it, which no outcome then reports.
1196	///
1197	/// Replaces `fn::sort_gnu_style`
1198	#[doc(alias = "sort_gnu_style")]
1199	fn reorder_gnu_style(parser: &mut ParserMut<'_, '_>) -> bool {
1200	    parser.set_needs_sort(false);
1201	    if parser.as_ref().in_literal() {
1202	        return false;
1203	    }
1204	    let len = parser.as_ref().args_len();
1205	    let mut insert = parser.as_ref().idx();
1206	    let mut at = insert;
1207	    let mut changed = false;
1208	    while let Some(arg) = parser.as_ref().args().get(at).copied() {
1209	        let Some((spec, needs_value)) = find_for_sort(parser.as_ref(), arg.as_c_str()) else {
1210	            at += 1;
1211	            continue;
1212	        };
1213	        if spec.kind() == Some(Kind::Literal) {
1214	            break;
1215	        }
1216	        let mut offset = 0;
1217	        if spec.kind() == Some(Kind::Value) && needs_value {
1218	            if at + 1 < len {
1219	                offset = 1;
1220	            } else if spec.usage().contains(Usage::VALUE_OPTIONAL) {
1221	                break;
1222	            } else {
1223	                parser.set_idx(at);
1224	                return true;
1225	            }
1226	        }
1227	        if at == 0 {
1228	            return false;
1229	        }
1230	        if let Some(run) = parser.args_mut().get_mut(insert..=at + offset) {
1231	            run.rotate_right(1 + offset);
1232	        }
1233	        insert += 1 + offset;
1234	        at += 1 + offset;
1235	        changed = true;
1236	    }
1237	    changed
1238	}
