484		/*
485		 * We've reached the first "bare" argument.  In POSIX mode, all
486		 * remaining items on the command line are arguments.  In GNU
487		 * mode, there may be long or short options after this.  Sort any
488		 * options up to this position then re-parse the current position.
489		 */
490		if (parser->needs_sort && sort_gnu_style(parser))
491			return cli_opt_parser_next(opt, parser);
