553	cli_opt_status_t cli_opt_parse(
554		cli_opt *opt,
555		const cli_opt_spec specs[],
556		char **args,
557		size_t args_len,
558		unsigned int flags)
559	{
560		cli_opt_parser parser;
561		const cli_opt_spec **given_specs;
562		size_t given_idx = 0;
563	
564		cli_opt_parser_init(&parser, specs, args, args_len, flags);
565	
566		given_specs = alloca(sizeof(const cli_opt_spec *) * (args_len + 1));
567	
568		while (cli_opt_parser_next(opt, &parser)) {
569			if (opt->status != CLI_OPT_STATUS_OK &&
570			    opt->status != CLI_OPT_STATUS_DONE)
571				return opt->status;
572	
573			if ((opt->spec->usage & CLI_OPT_USAGE_STOP_PARSING))
574				return (opt->status = CLI_OPT_STATUS_DONE);
575	
576			given_specs[given_idx++] = opt->spec;
577		}
578	
579		given_specs[given_idx] = NULL;
580	
581		return validate_required(opt, specs, given_specs);
582	}
