606	static int spec_name_fprint(FILE *file, const cli_opt_spec *spec)
607	{
608		int error;
609	
610		if (spec->type == CLI_OPT_TYPE_ARG)
611			error = fprintf(file, "%s", spec->value_name);
612		else if (spec->type == CLI_OPT_TYPE_ARGS)
613			error = fprintf(file, "%s", spec->value_name);
614		else if (spec->alias && !(spec->usage & CLI_OPT_USAGE_SHOW_LONG))
615			error = fprintf(file, "-%c", spec->alias);
616		else
617			error = fprintf(file, "--%s", spec->name);
618	
619		return error;
620	}
621	
622	int cli_opt_status_fprint(
623		FILE *file,
624		const char *command,
625		const cli_opt *opt)
626	{
627		const cli_opt_spec *choice;
628		int error;
629	
630		if (command && (error = fprintf(file, "%s: ", command)) < 0)
631			return error;
632	
633		switch (opt->status) {
634		case CLI_OPT_STATUS_DONE:
635			error = fprintf(file, "finished processing arguments (no error)\n");
636			break;
637		case CLI_OPT_STATUS_OK:
638			error = fprintf(file, "no error\n");
639			break;
640		case CLI_OPT_STATUS_UNKNOWN_OPTION:
641			error = fprintf(file, "unknown option: %s\n", opt->arg);
642			break;
643		case CLI_OPT_STATUS_MISSING_VALUE:
644			if ((error = fprintf(file, "argument '")) < 0 ||
645			    (error = spec_name_fprint(file, opt->spec)) < 0 ||
646			    (error = fprintf(file, "' requires a value.\n")) < 0)
647				break;
648			break;
649		case CLI_OPT_STATUS_MISSING_ARGUMENT:
650			if (spec_is_choice(opt->spec)) {
651				int is_choice = 1;
652	
653				if (spec_is_choice((opt->spec)+1))
654					error = fprintf(file, "one of");
655				else
656					error = fprintf(file, "either");
657	
658				if (error < 0)
659					break;
660	
661				for (choice = opt->spec; is_choice; ++choice) {
662					is_choice = spec_is_choice(choice);
663	
664					if (!is_choice)
665						error = fprintf(file, " or");
666					else if (choice != opt->spec)
667						error = fprintf(file, ",");
668	
669					if ((error < 0) ||
670					    (error = fprintf(file, " '")) < 0 ||
671					    (error = spec_name_fprint(file, choice)) < 0 ||
672					    (error = fprintf(file, "'")) < 0)
673						break;
674	
675					if (!spec_is_choice(choice))
676						break;
677				}
678	
679				if ((error < 0) ||
680				    (error = fprintf(file, " is required.\n")) < 0)
681					break;
682			} else {
683				if ((error = fprintf(file, "argument '")) < 0 ||
684				    (error = spec_name_fprint(file, opt->spec)) < 0 ||
685				    (error = fprintf(file, "' is required.\n")) < 0)
686					break;
687			}
688	
689			break;
690		default:
691			error = fprintf(file, "unknown status: %d\n", opt->status);
692			break;
693		}
694	
695		return error;
696	}
