461	cli_opt_status_t cli_opt_parser_next(cli_opt *opt, cli_opt_parser *parser)
462	{
463		assert(opt && parser);
464	
465		memset(opt, 0x0, sizeof(cli_opt));
466	
467		if (parser->idx >= parser->args_len) {
468			opt->args_len = parser->in_args;
469			return CLI_OPT_STATUS_DONE;
470		}
471	
472		/* Handle options in long form, those beginning with "--" */
473		if (strncmp(parser->args[parser->idx], "--", 2) == 0 &&
474		    !parser->in_short &&
475		    !parser->in_literal)
476			return parse_long(opt, parser);
477	
478		/* Handle options in short form, those beginning with "-" */
479		else if (parser->in_short ||
480		         (strncmp(parser->args[parser->idx], "-", 1) == 0 &&
481			  !parser->in_literal))
482			return parse_short(opt, parser);
483	
484		/*
485		 * We've reached the first "bare" argument.  In POSIX mode, all
486		 * remaining items on the command line are arguments.  In GNU
487		 * mode, there may be long or short options after this.  Sort any
488		 * options up to this position then re-parse the current position.
489		 */
490		if (parser->needs_sort && sort_gnu_style(parser))
491			return cli_opt_parser_next(opt, parser);
492	
493		return parse_arg(opt, parser);
494	}
