/// The gateway through which the CLI's remaining C calls this module once it has switched:
/// `cli_opt_parser_init` and `cli_opt_parser_next`, which `main.c` calls, `cli_opt_parse`, which
/// each `cmd_*.c` calls, `cli_opt_foreach`, which `common.c` calls, and `cli_opt_status_fprint`,
/// which `main.c` and `opt_usage.c` call, each checked against its raw binding's signature, so
/// that a C declaration that drifts fails to build.
#[cfg(feature = "ffi-export-src-cli-opt-c")]
#[expect(
    unsafe_code,
    reason = "the C ABI exports of opt.c's entry points, which adopt the pointers C passes"
)]
mod ffi_export {
    use core::ffi::{CStr, c_char, c_int, c_uint, c_void};
    use core::ops::ControlFlow;
    use core::slice;

    use ffibox::callback::barrier;
    use ffibox::{CMutSeam, CRefSeam, CZeroable};
    use glibc_bindings::libc::csu::errno_loc::set_errno;
    use glibc_bindings::libc::libio::genops::FileRef;
    use nix::errno::Errno;

    use super::{
        Arg, FileWriter, ForeachCallbackFn, Opt, OptRef, ParseFlags, Parser, ParserMut, Spec,
        SpecTable, for_each, parse,
    };
    use crate::sys::git2 as sys;

    // Each export has its raw binding's type: the array's elements coerce to one function
    // pointer type only when their signatures agree.
    const _: () = {
        let _ = [sys::cli_opt_parser_init, cli_opt_parser_init];
        let _ = [sys::cli_opt_parser_next, cli_opt_parser_next];
        let _ = [sys::cli_opt_parse, cli_opt_parse];
        let _ = [sys::cli_opt_foreach, cli_opt_foreach];
        let _ = [sys::cli_opt_status_fprint, cli_opt_status_fprint];
    };

    /// The `args_len` arguments at `args`, as C passes a parse its `argv`, borrowed exclusively
    /// for `'p`; it aborts on a `NULL` array of arguments with `args_len` other than 0, or a
    /// `NULL` argument within it.
    ///
    /// # Safety
    ///
    /// `args` addresses `args_len` arguments, each a NUL-terminated string, unless `args_len` is
    /// 0: the array and the strings live, the strings unchanged, for `'p`, and nothing but the
    /// parse given them reaches the array meanwhile.
    unsafe fn adopt_args<'p>(args: *mut *mut c_char, args_len: usize) -> &'p mut [Arg<'p>] {
        if args_len == 0 {
            return &mut [];
        }
        if args.is_null() {
            std::process::abort();
        }
        // SAFETY: the caller's contract: `args` addresses `args_len` readable elements.
        let elements = unsafe { slice::from_raw_parts(args.cast_const(), args_len) };
        if elements.iter().any(|arg| arg.is_null()) {
            std::process::abort();
        }
        // SAFETY: the `args_len` elements are non-null, as just checked, and each a NUL-terminated
        // string that lives, unchanged, for `'p`, which only the parse given them reaches
        // meanwhile, by the caller's contract: valid `Arg`s, which are `#[repr(transparent)]` over
        // a non-null `char *`, borrowed exclusively for as long.
        unsafe { slice::from_raw_parts_mut(args.cast::<Arg<'p>>(), args_len) }
    }

    /// Writes `opt` to `*out` and returns its status, as C's parser fills the outcome its caller
    /// gives it and returns that outcome's status. It aborts on a `NULL` `out`.
    ///
    /// # Safety
    ///
    /// `out` is `NULL` or valid for a write of a `cli_opt`.
    unsafe fn write_outcome(out: *mut sys::cli_opt, opt: Opt<'_>) -> sys::cli_opt_status_t {
        if out.is_null() {
            std::process::abort();
        }
        let status = opt.as_ref().raw_status();
        // SAFETY: `out` is non-null and valid for a write of a `cli_opt`, the caller's contract;
        // `Opt` is `#[repr(transparent)]` over it, and the write reads nothing of the old value,
        // which needs no drop.
        unsafe { out.cast::<Opt<'_>>().write(opt) };
        status
    }

    /// `cli_opt_parser_init`: [`Parser::new`] over the table at `specs` and the `args_len`
    /// arguments at `args`, written to `*parser`, which it overwrites whole, as C's `memset`
    /// does. A panic aborts, as it cannot fail.
    ///
    /// The C stores `specs` and `args` unread, and the parse that follows reads them; here they
    /// are read at once, so a `NULL` parser, a `NULL` table, a `NULL` array of arguments with
    /// `args_len` other than 0, or a `NULL` argument within it aborts, where the C, built with
    /// `NDEBUG`, writes through the `NULL` parser or faults in that parse.
    ///
    /// # Safety
    ///
    /// `parser` is valid for a write of a `cli_opt_parser`; `specs` is a spec table, as
    /// [`SpecTable::from_ptr`] adopts one, and `args` addresses `args_len` arguments, each a
    /// NUL-terminated string, unless `args_len` is 0: all of them live, the strings unchanged,
    /// while C uses the parser, and nothing but that parse reaches the array meanwhile.
    #[unsafe(no_mangle)]
    unsafe extern "C" fn cli_opt_parser_init(
        parser: *mut sys::cli_opt_parser,
        specs: *const sys::cli_opt_spec,
        args: *mut *mut c_char,
        args_len: usize,
        flags: c_uint,
    ) {
        if parser.is_null() {
            std::process::abort();
        }
        // SAFETY: the caller's contract: `specs` is a table that lives, unchanged, while C uses
        // the parser, the lifetime this adoption takes.
        let Some(table) = (unsafe { SpecTable::from_ptr(specs) }) else {
            std::process::abort();
        };
        // SAFETY: the caller's contract: `args` addresses `args_len` arguments that live, the
        // strings unchanged, while C uses the parser, which only that parse reaches meanwhile.
        let args = unsafe { adopt_args(args, args_len) };
        let flags = ParseFlags::from_bits_retain(flags);
        let new = barrier(|| Parser::new(table, args, flags), || std::process::abort());
        // SAFETY: `parser` is non-null and valid for a write of a `cli_opt_parser`, the
        // caller's contract; `Parser` is `#[repr(transparent)]` over it, and the write reads
        // nothing of the old value, which needs no drop.
        unsafe { parser.cast::<Parser<'_>>().write(new) };
    }

    /// `cli_opt_parser_next`: [`ParserMut::parse_next`] of `*parser`, whose outcome it writes to
    /// `*opt`, overwriting it whole, as C's `memset` does, and whose status it returns. A `NULL`
    /// outcome or parser aborts, where the C, built with `NDEBUG`, writes through it; so does a
    /// panic, which no status the C returns describes.
    ///
    /// # Safety
    ///
    /// `opt` is valid for a write of a `cli_opt`, and `parser` is a parser `cli_opt_parser_init`
    /// set up and only this export has changed since: a valid `Parser`, as
    /// [`Parser`]'s adoption asks, whose table and arguments live, unchanged but for the order
    /// a parse gives the arguments, while C uses the parser and the outcomes it gives, and which
    /// nothing else reaches during the call.
    #[unsafe(no_mangle)]
    unsafe extern "C" fn cli_opt_parser_next(
        opt: *mut sys::cli_opt,
        parser: *mut sys::cli_opt_parser,
    ) -> sys::cli_opt_status_t {
        // SAFETY: the caller's contract: `parser` is a valid parser that nothing else reaches
        // during the call, whose table and arguments live while C uses it and its outcomes, the
        // lifetime this adoption takes.
        let Some(mut parser) = (unsafe { ParserMut::from_ptr(parser) }) else {
            std::process::abort();
        };
        let next = barrier(|| parser.parse_next(), || std::process::abort());
        // SAFETY: the caller's contract: `opt` is valid for a write of a `cli_opt`.
        unsafe { write_outcome(opt, next) }
    }

    /// `cli_opt_parse`: [`parse`] of the `args_len` arguments at `args` against the table at
    /// `specs`, whose outcome, the one that failed or the last, it writes to `*opt`, overwriting it
    /// whole, and whose status it returns: `CLI_OPT_STATUS_DONE` once every argument is parsed and
    /// every requirement met. A `NULL` outcome, table or array of arguments, or a `NULL` argument
    /// within it, aborts, where the C, built with `NDEBUG`, writes or reads through it; so does a
    /// panic, which no status the C returns describes.
    ///
    /// # Safety
    ///
    /// `opt` is valid for a write of a `cli_opt`; `specs` is a spec table, as
    /// [`SpecTable::from_ptr`] adopts one, and `args` addresses `args_len` arguments, each a
    /// NUL-terminated string, unless `args_len` is 0: all of them live, the strings unchanged,
    /// while C uses the outcome and the specs' variables, and nothing but this parse reaches the
    /// array during the call.
    #[unsafe(no_mangle)]
    unsafe extern "C" fn cli_opt_parse(
        opt: *mut sys::cli_opt,
        specs: *const sys::cli_opt_spec,
        args: *mut *mut c_char,
        args_len: usize,
        flags: c_uint,
    ) -> sys::cli_opt_status_t {
        if opt.is_null() {
            std::process::abort();
        }
        // SAFETY: the caller's contract: `specs` is a table that lives, unchanged, while C uses
        // the outcome and the variables, the lifetime this adoption takes.
        let Some(table) = (unsafe { SpecTable::from_ptr(specs) }) else {
            std::process::abort();
        };
        // SAFETY: the caller's contract: `args` addresses `args_len` arguments that live, the
        // strings unchanged, as long, which only this parse reaches during the call.
        let args = unsafe { adopt_args(args, args_len) };
        let flags = ParseFlags::from_bits_retain(flags);
        let outcome = barrier(
            || match parse(table, args, flags) {
                Ok((done, _)) => done,
                Err(failed) => failed,
            },
            || std::process::abort(),
        );
        // SAFETY: the caller's contract: `opt`, non-null, is valid for a write of a `cli_opt`.
        unsafe { write_outcome(opt, outcome) }
    }

    /// `cli_opt_foreach`: [`for_each`] of the `args_len` arguments at `args` against the table at
    /// `specs`, calling `callback` with each outcome and `callback_data`: the first value other
    /// than 0 it returns, or 0 once every argument is parsed. A panic is reported as -1, a failure
    /// `common.c`, the CLI's caller, reads as any other. A `NULL` table, callback or array of
    /// arguments, or a `NULL` argument within it, aborts, where the C, built with `NDEBUG`, reads
    /// or calls through it.
    ///
    /// # Safety
    ///
    /// `specs` is a spec table, as [`SpecTable::from_ptr`] adopts one, and `args` addresses
    /// `args_len` arguments, each a NUL-terminated string, unless `args_len` is 0: all of them
    /// live, the strings unchanged, while C uses the specs' variables, and nothing but this parse
    /// reaches the array during the call. `callback` may be called with `callback_data` as its
    /// second argument, any number of times, on the calling thread, during the call, with an
    /// outcome it only reads and whose address it does not keep once it returns, as
    /// [`ForeachCallbackFn::from_c`] asks.
    #[unsafe(no_mangle)]
    unsafe extern "C" fn cli_opt_foreach(
        specs: *const sys::cli_opt_spec,
        args: *mut *mut c_char,
        args_len: usize,
        flags: c_uint,
        callback: Option<unsafe extern "C" fn(*mut sys::cli_opt, *mut c_void) -> c_int>,
        callback_data: *mut c_void,
    ) -> c_int {
        // SAFETY: the caller's contract: `specs` is a table that lives, unchanged, while C uses
        // the variables, the lifetime this adoption takes.
        let Some(table) = (unsafe { SpecTable::from_ptr(specs) }) else {
            std::process::abort();
        };
        let Some(callback) = callback else {
            std::process::abort();
        };
        // SAFETY: the caller's contract: `args` addresses `args_len` arguments that live, the
        // strings unchanged, as long, which only this parse reaches during the call.
        let args = unsafe { adopt_args(args, args_len) };
        let flags = ParseFlags::from_bits_retain(flags);
        // SAFETY: the caller's contract: `callback` may be called with `callback_data`, on this
        // thread, during this call, which the callable does not outlive, with outcomes it only
        // reads and does not keep.
        let callback = unsafe { ForeachCallbackFn::from_c(callback, callback_data) };
        barrier(
            || match for_each(table, args, flags, callback) {
                ControlFlow::Continue(()) => 0,
                ControlFlow::Break(code) => code.get(),
            },
            || -1,
        )
    }

    /// `cli_opt_status_fprint`: [`OptRef::write_status`] of `*opt` to the stream `file`, after
    /// `command` when it is not `NULL`, read from the table that starts at the outcome's spec,
    /// which holds that spec's later choices. Returns 0 once it is written, and -1 when a write
    /// fails, as `opt.h` documents, `errno` holding the stream's error, or `EINVAL` for an
    /// outcome the message cannot name, a missing value or argument with no spec, whose spec the
    /// C reads through a null pointer. A panic is reported as a failure.
    ///
    /// The C returns the count of its last piece's `fprintf` on success: no caller reads it. A
    /// `command` or an argument that is not UTF-8 is written with each invalid sequence replaced
    /// by U+FFFD, since libc's wrapper writes text: [`FileWriter`]'s departure.
    ///
    /// # Safety
    ///
    /// `file` is an open stream that stays open during the call, every other access to it
    /// holding its lock, as C's stdio routines do; `command` is `NULL` or a NUL-terminated
    /// string; and `opt` is an outcome C's parser wrote, or a zeroed one: a valid `Opt`, as
    /// [`Opt`](super::Opt)'s adoption asks, whose spec, when it has one, is an element of a spec
    /// table [`SpecTable::from_ptr`] adopts from it. All of them live, unchanged, for the call.
    #[unsafe(no_mangle)]
    unsafe extern "C" fn cli_opt_status_fprint(
        file: *mut sys::FILE,
        command: *const c_char,
        opt: *const sys::cli_opt,
    ) -> c_int {
        // SAFETY: the caller's contract: `file` is an open stream for the call, every other
        // access holding its lock, as `FileRef::from_ptr` asks of a stream.
        let Some(file) = (unsafe { FileRef::from_ptr(file) }) else {
            set_errno(Errno::EINVAL as c_int);
            return -1;
        };
        // SAFETY: the caller's contract: a non-null `command` is a NUL-terminated string that
        // lives, unchanged, for the call.
        let command = (!command.is_null()).then(|| unsafe { CStr::from_ptr(command) });
        // SAFETY: the caller's contract: `opt` is a valid outcome that lives, unchanged, for
        // the call, the lifetime this adoption takes.
        let Some(opt) = (unsafe { OptRef::from_ptr(opt.cast_mut()) }) else {
            set_errno(Errno::EINVAL as c_int);
            return -1;
        };
        let end = [Spec::zeroed()];
        let specs = opt
            .spec()
            // SAFETY: the caller's contract: the outcome's spec is an element of a table
            // ended by a spec of kind `CLI_OPT_TYPE_NONE`, live and unchanged for the call.
            .and_then(|spec| unsafe { SpecTable::from_ptr(spec.as_ptr()) })
            .or_else(|| SpecTable::new(&end));
        let Some(specs) = specs else {
            set_errno(Errno::EINVAL as c_int);
            return -1;
        };
        let command = command.map(CStr::to_string_lossy);
        let written = barrier(
            || opt.write_status(&mut FileWriter(file), command.as_deref(), specs),
            || Err(std::io::Error::other("panicked")),
        );
        match written {
            Ok(()) => 0,
            Err(e) => {
                // The stream's failures leave `errno` as `fprintf` set it; the refusal of an
                // outcome without a spec sets none of its own.
                if e.kind() == std::io::ErrorKind::InvalidInput && e.raw_os_error().is_none() {
                    set_errno(Errno::EINVAL as c_int);
                }
                -1
            }
        }
    }
}

/// The integer forms of [`Kind`] and [`Status`], compared with the constants `opt.h` defines,
/// through the raw bindings, which only constants reach: no C runs.
#[cfg(test)]
mod equiv_priv {

content.content:
//! `libio/iofwrite.c`: `fwrite`, the byte-exact write to a C stream.
//!
//! [`FileRef::write_all`] hands bytes, any bytes, NUL and invalid UTF-8 included, to
//! `fwrite(bytes, 1, len, stream)`, so that they land in the stream's own buffer, in order
//! with what the C that shares the stream writes. It is the write an [`io::Write`] over a C
//! stream makes, one call per `write`, though it implements no such trait itself: a `flush`
//! would need `fflush`, which is not bound.
//!
//! [`FileRef::write_all`]: crate::libc::libio::genops::FileRef::write_all
//! [`io::Write`]: std::io::Write

#[expect(
    unsafe_code,
    reason = "calls ferror and fwrite on a borrowed stream, under its lock"
)]
mod ffi_import {
    use core::ffi::{c_int, c_void};
    use std::io;

    use crate::libc::csu::errno_loc::{errno, set_errno};
    use crate::libc::ffi;
    use crate::libc::libio::genops::{FileRef, StreamLock};

    impl FileRef<'_> {
        /// Wraps `fn::fwrite`
        ///
        /// Writes every byte of `bytes` to the stream, as `fwrite(bytes, 1, bytes.len(), stream)`
        /// does, or fails. The bytes are written as they are: a NUL byte, or bytes that are not
        /// UTF-8, are written like any other.
        ///
        /// The write holds the stream's lock from start to end, taken with `flockfile`, whatever
        /// the stream's locking mode. A stream C set to `FSETLOCKING_BYCALLER` is locked too,
        /// although glibc's own `fwrite` would skip the lock on it. So one call's bytes are never
        /// interleaved with another thread's write to the stream, and the call waits while
        /// another thread holds the lock. The calling thread may already hold it, as the lock is
        /// recursive. A stream that has no lock is refused, as below.
        ///
        /// The bytes land in the stream's buffer, and reach the file when the buffering mode the
        /// C gave the stream says, or at `fflush` or `fclose`. A stream that has no orientation
        /// yet is oriented for bytes, as `fwrite` orients it.
        ///
        /// An empty `bytes` succeeds without touching the stream but for its lock, as `fwrite`
        /// of no bytes returns at once: it orients nothing, and does not fail on a stream that
        /// is wide-oriented or not open for writing, where `print("")`, which is
        /// `fprintf(stream, "%s", "")`, orients the stream or fails.
        ///
        /// # Failure
        ///
        /// `fwrite` reports a failure by returning fewer bytes than it was given, with one
        /// exception: when the bytes fit the buffer of a line-buffered stream and end with a
        /// newline, and the flush that newline calls for fails, it returns the full count.
        /// glibc's `fprintf` reports the same failure as one. A failed write sets the stream's
        /// error indicator, so the call fails when `fwrite` returns a short count, and when it
        /// returns the full count but the stream's error indicator, clear before the call, is
        /// set after it: read with `ferror`, under the same hold of the lock. Two such failures
        /// cannot be told from a success, which is what the call reports, as `fwrite` does,
        /// where `fprintf` fails:
        ///
        /// - one on a stream whose error indicator is already set, by an earlier failure nothing
        ///   has cleared (`clearerr`); and
        /// - one that sets no indicator: a flush that fails in the seek glibc makes before it
        ///   writes, back over bytes read into the buffer and not yet consumed, on a stream C read
        ///   and then wrote without a positioning call, which ISO C leaves undefined, over a file
        ///   that cannot seek, such as a pipe or a socket (`ESPIPE`). The bytes stay in the buffer,
        ///   and `errno` is left as it was.
        ///
        /// A failure is not retried, and the count `fwrite` returned is not reported: part of
        /// `bytes` may have reached the stream's buffer, its storage or its file, and a failed
        /// flush discards what the buffer held.
        ///
        /// # Errors
        ///
        /// - [`io::ErrorKind::Unsupported`], when the stream has no lock for `flockfile` to take:
        ///   the stream glibc hands the handler of a conversion that `register_printf_specifier`
        ///   adds, over printf's own buffer, whose lock is NULL. Nothing is written, and `errno` is
        ///   left as it was.
        /// - `errno`'s error, when `fwrite` fails and sets it: `EBADF` for a stream not open for
        ///   writing, which sets its error indicator and has nothing written to it, and the error
        ///   of the write that flushes the buffer, such as `ENOSPC`, `EPIPE` or `EIO`. `errno`
        ///   keeps that error, as C's does.
        /// - [`io::ErrorKind::Other`], with no OS error, when `fwrite` fails without setting
        ///   `errno`. A stream that is wide-oriented (by `fwide` or a wide-character write) does
        ///   that, and nothing is written to it or to its error indicator. A cookie stream whose
        ///   write function fails without setting `errno` does it too. `errno` is left as it was.
        ///
        /// On success `errno` is left as it was too.
        #[doc(alias = "fwrite")]
        pub fn write_all(&self, bytes: &[u8]) -> io::Result<()> {
            let lock = self.lock()?;
            let saved = errno();
            // `fwrite` reports some failures without setting `errno`: cleared, so that what it
            // holds after the call is what the call set.
            set_errno(0);
            let call = write_locked(&lock, bytes);
            drop(lock);
            let result = outcome(bytes.len(), call);
            if result.is_ok() || call.errno == 0 {
                set_errno(saved);
            }
            result
        }
    }

    /// What one `fwrite` call reported: its return, the `errno` it left after it was cleared,
    /// and the stream's error indicator before and after it.
    #[derive(Clone, Copy)]
    struct Call {
        /// The count `fwrite` returned.
        written: usize,
        /// `errno` after the call, `0` when the call set none.
        errno: c_int,
        /// Whether the stream's error indicator was set before the call.
        error_before: bool,
        /// Whether it was set after the call.
        error_after: bool,
    }

    /// The outcome of a `fwrite` of `len` bytes that reported `call`: a failure when it
    /// returned a short count, or when it set the stream's error indicator, which was clear
    /// before it; the error `errno` reports, or one with no OS error when it reports none.
    fn outcome(len: usize, call: Call) -> io::Result<()> {
        let failed = call.written < len || (call.error_after && !call.error_before);
        if !failed {
            Ok(())
        } else if call.errno == 0 {
            Err(io::Error::other("fwrite failed without setting errno"))
        } else {
            Err(io::Error::from_raw_os_error(call.errno))
        }
    }

    /// Writes `bytes` to the stream `lock` holds with `fwrite(bytes, 1, len, stream)`, reading
    /// the stream's error indicator before and after the call and `errno` right after it, all
    /// under the one hold of the lock.
    fn write_locked(lock: &StreamLock<'_>, bytes: &[u8]) -> Call {
        let p = lock.as_ptr();
        // SAFETY: the stream is open, and locked by this thread, while `lock` lives
        // (`FileRef::lock`). `ferror` only reads its error flag, taking the recursive lock this
        // thread holds.
        let error_before = unsafe { ffi::ferror(p) } != 0;
        // SAFETY: the stream is open and locked by this thread, as above, and its pointer may be
        // written under that lock. `bytes` is valid for reads of `bytes.len()` bytes, elements
        // of size 1, so that the request, their product, cannot overflow; `fwrite` copies from
        // it during the call only, and keeps no pointer to it. An empty `bytes` is a dangling
        // pointer that `fwrite` returns before reading. The stream's lock serializes this write
        // with every other access to it, which `FileRef::from_ptr`'s contract makes hold the
        // lock too.
        let written = unsafe { ffi::fwrite(bytes.as_ptr().cast::<c_void>(), 1, bytes.len(), p) };
        // Read before anything else runs that may change it.
        let errno = errno();
        // SAFETY: as for the first `ferror`.
        let error_after = unsafe { ffi::ferror(p) } != 0;
        Call {
            written,
            errno,
            error_before,
            error_after,
        }
    }

    #[cfg(test)]
    mod unit_priv {
        use std::io;

        use super::{Call, outcome};
        use crate::libc::ffi;

        fn call(written: usize, errno: i32, error_before: bool, error_after: bool) -> Call {
            Call {
                written,
                errno,
                error_before,
                error_after,
            }
        }

        #[test]
        fn a_full_count_with_no_new_error_is_the_success() {
            outcome(0, call(0, 0, false, false)).unwrap();
            outcome(5, call(5, 0, false, false)).unwrap();
            // An `errno` a successful call left is no failure.
            outcome(5, call(5, ffi::EINTR, false, false)).unwrap();
            // An indicator set before the call, and still set, tells nothing of it.
            outcome(5, call(5, 0, true, true)).unwrap();
            outcome(5, call(5, ffi::ENOSPC, true, true)).unwrap();
            outcome(usize::MAX, call(usize::MAX, 0, false, false)).unwrap();
        }

        #[test]
        fn a_short_count_is_a_failure() {
            let e = outcome(5, call(2, ffi::ENOSPC, false, true)).unwrap_err();
            assert_eq!(e.raw_os_error(), Some(ffi::ENOSPC));
            let e = outcome(5, call(0, ffi::EBADF, true, true)).unwrap_err();
            assert_eq!(e.raw_os_error(), Some(ffi::EBADF));
            // A wide stream's: no `errno`, and no indicator.
            let e = outcome(5, call(0, 0, false, false)).unwrap_err();
            assert_eq!(e.kind(), io::ErrorKind::Other);
            assert_eq!(e.raw_os_error(), None);
        }

        /// number of bytes written, `text.len()`.
        ///
        /// The write holds the stream's lock from start to end, taken with `flockfile`, whatever
        /// the stream's locking mode. A stream C set to `FSETLOCKING_BYCALLER` is locked too,
        /// although glibc's own `fprintf` would skip the lock on it. So one call's text is
        /// never interleaved with another thread's write to the stream, and the call waits
        /// while another thread holds the lock. The calling thread may already hold it, as
        /// the lock is recursive. A stream that has no lock is refused, as below.
        ///
        /// The text lands in the stream's buffer, and reaches the file when the buffering mode
        /// the C gave the stream says, or at `fflush` or `fclose`.
        ///
        /// # Errors
        ///
        /// - [`io::ErrorKind::InvalidInput`], when `text` holds a NUL byte, which a C string cannot
        ///   carry. Nothing is written, and `errno` is left as it was.
        /// - [`io::ErrorKind::Unsupported`], when the stream has no lock for `flockfile` to take:
        ///   the stream glibc hands the handler of a conversion that `register_printf_specifier`
        ///   adds, over printf's own buffer, whose lock is NULL. Nothing is written, and `errno` is
        ///   left as it was.
        /// - `errno`'s error, when `fprintf` fails and sets it: `EBADF` for a stream not open for
        ///   writing, which sets its error indicator and has nothing written to it; the error of
        ///   the write that flushes the buffer, such as `ENOSPC`, `EPIPE` or `EIO`, after part of
        ///   `text` may have reached the stream; and `EOVERFLOW` for a `text` longer than `INT_MAX`
        ///   bytes, whose count `fprintf` cannot return, though the text is written. `errno` keeps
        ///   that error, as C's does.
        /// - [`io::ErrorKind::Other`], with no OS error, when `fprintf` fails without setting
        ///   `errno`. A stream that is wide-oriented (by `fwide` or a wide-character write) does
        ///   that, and nothing is written to it. A cookie stream whose write function fails without
