                sys::cli_opt_parser::set_needs_sort_raw(self.as_mut_ptr(), needs_sort.into());
            };
        }

        /// Sets whether every argument from here on is literal.
        ///
        /// Wraps `fld::cli_opt_parser.in_literal`
        #[doc(alias = "cli_opt_parser.in_literal")]
